  y[18] = x[18] * 4.1073000000000000e+01 * XWinv;
  y[19] = x[19] * 4.2081000000000003e+01 * XWinv;
  y[20] = x[20] * 5.6064000000000000e+01 * XWinv;
  y[21] = x[21] * 5.5099999999999994e+01 * XWinv;
  y[22] = x[22] * 5.6107999999999997e+01 * XWinv;
  y[23] = x[23] * 6.9126999999999995e+01 * XWinv;
  y[24] = x[24] * 7.0134999999999991e+01 * XWinv;
  y[25] = x[25] * 8.4162000000000006e+01 * XWinv;
  y[26] = x[26] * 9.8188999999999993e+01 * XWinv;
  y[27] = x[27] * 1.1221599999999999e+02 * XWinv;
  y[28] = x[28] * 1.2624299999999999e+02 * XWinv;
  y[29] = x[29] * 1.2725099999999999e+02 * XWinv;
