           (16.043030 * 16.043030 * 45.990000);
  bi[10] = 0.08664 * Rcst * Tci[10] / (16.043030 * 45.990000);
  acentric_i[10] = 0.011000;

  // species 11: CH2O
  Tci[11] = 1.316 * EPS[11];
